fn solve(s: Vec<char>) -> Vec<char> {
    // We only consider the first three characters.
    let a = s[0];
    let b = s[1];
    let c = s[2];

    // Check if they are pairwise distinct.
    let is_permutation = a != b && a != c && b != c;

    // Return "Yes\n" if they form a permutation of {'a','b','c'}, else "No\n".
    let answer = if is_permutation { "Yes\n" } else { "No\n" };
    answer.chars().collect()
}

